mapping=json.loads(Path('work/pauly-action-audio-map.json').read_text('utf8'));src=Path('work/pauly/PaulyMouse_Win10/Data/PMNL/SOUNDS');items=[]
for p in sorted(src.glob('SEF*.AIF')):
 if p.stem=='SEF00009':continue # Nonverbal musical cue, preserved unchanged.
 number=int(re.search(r'SEF(\d{3})',p.name)[1]);room=number//100
 if number%100==0:text=REACTIONS[room][0 if 'N1' in p.stem else 1]
 else:text=LINES[room][number]
 if p.name=='SEF803BN.AIF':text='¡Aaah! ¡Mi siesta! ¡Yo estaba durmiendo!'
 animal=mapping.get(p.name,{}).get('animal',0);name=mapping.get(p.name,{}).get('name','Pauly')
 female=animal%3==0 or animal==0;voice='es-MX-DaliaNeural' if female else 'es-MX-JorgeNeural';pitch='+35Hz' if female else '+20Hz';rate='+5%'
